effect.shader:

    vec4 newLayer( vec4 a, vec4 b) {
    return a * (1. - b.a) + b;
    }

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord.xy

   /////////////////////////

        float greyScale(in vec3 col) {
            return dot(col, vec3(0.2126, 0.7152, 0.0722));
        }

        mat2 rotate2d(float angle){
            return mat2(cos(angle), -sin(angle), sin(angle),cos(angle));
        }

   /////////////////////////
    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

        vec2 image_size = getTexSize(inputImg.size);
        vec2 iRes = vec2(acScreenSize.x, acScreenSize.y);

        vec2 TanRyu;
        TanRyu = acScreenNorm.st; 

        /////////////////////////

    	vec4 fragColor;


            vec2 uv = TanRyu;
            // vec2 uv = fragCoord.xy / iResolution.xy;
            vec4 colX = texture2DCv(xdist.texture, uv); 
            // vec3 col = texture2DCv(inputImg.texture, uv).rgb; 
            vec4 col = colX;
            if (greyscale) col.rgb = vec3(greyScale(col.rgb));
            if (greyscale) col.rgb = vec3(1.0) - col.rgb;

            uv *= iRes.xy;
            vec2 p = rotate2d(angle) * uv * scale; 

            float pattern;
            vec3 xnxx;
            if( type==0 ) {
           	pattern = sin( p.x ) * amount;
            xnxx = col.rgb * 10. * satt - 5. + pattern; }

            else if( type==1 ) {
            pattern = sin( p.x ) * sin( p.y ) * amount;
            xnxx = col.rgb * 10. * satt - 5. + pattern; }

            else if( type==2 ) {
            // col.rgb = vec3(greyScale(col.rgb));
            pattern = texture2DCv(noisexx.texture, fragCoord / 4. * scale).r*amount/5.;
            xnxx = step(pattern, col.rgb); }

            fragColor = vec4( xnxx, 1.0 );
            // fragColor = vec4( xnxx, 1.0 );

    	vec4 factor = mix(texColorX,fragColor,1.0);

        vec4 resultfinal;
        if( blendMode==0 ) {                // normal
            resultfinal = (factor * 1.0) * texColor.a;
            // resultfinal = (newLayer(texColor, factor) * 1.0) * texColor.a;
        } else if( blendMode==1 ) {         // multiply
            factor *= 1.0;
            vec4 c = factor + vec4(1.)*(1.-factor.a);
            resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( blendMode==2 ) {         // screen
            factor *= 1.0;
            resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }

    	// gl_FragColor = colX;
    	gl_FragColor = mix(texColor, resultfinal, alpha);
    	// }
    }
